'use strict';
const growthConfig={name:'balanced',interval:12,age:90,towns:8,transition:25};let growthMapName=mapSpec.id,growthAvailable=[],gridCache=null,growthStateRef=null,pendingSeedPlan=null;
function configureGrowth(){growthStateRef=null;}
function farEnough(p,c,d=190){return Math.hypot(p.x-c.x,p.y-c.y)>=d&&(Math.abs(p.x-c.x)>=190||Math.abs(p.y-c.y)>=145);}
function growthGrid(){if(!gridCache){gridCache=[];let b=mapSpec.bounds;for(let y=b.ymin;y<=b.ymax;y+=40)for(let x=b.xmin;x<=b.xmax;x+=40)if(cityBuildable(x,y,2))gridCache.push({x,y});}return gridCache;}
function freePoints(){return growthGrid().filter(p=>realCities().every(c=>c.removed||farEnough(p,c)));}
function clusterMembers(r,opened=false){return realCities().filter(c=>!c.removed&&!c.outlying&&c.regionId===r.id&&(!opened||!c.dormant));}
function growthState(){if(S.atlasGrowth&&growthStateRef===S.atlasGrowth)return growthStateRef;cityRegions();for(let r of S.cityRegions){r.discoveredAt??=0;r.nextLocalAt=Infinity;}S.atlasGrowth??={profile:'balanced',map:mapSpec.id,focus:0,next:16,lastDay:-1,readyAt:null,paused:false,births:[],maturity:[],exhaustedAt:null,spaceChecks:0};growthStateRef=S.atlasGrowth;growthAvailable=freePoints();pendingSeedPlan=null;return growthStateRef;}
function growthRadius(r){return Math.min(760,Math.max(440,220*Math.sqrt(clusterMembers(r).length)));}
function growthDirections(r){return new Set(clusterMembers(r,true).filter(c=>Math.hypot(c.x-r.x,c.y-r.y)>=100).map(c=>(c.x>=r.x?1:0)+(c.y>=r.y?2:0)));}
function reservedForOther(p,rid){return cityRegions().some(r=>r.id!==rid&&(r.reservedPoints||[]).some(q=>!realCities().some(c=>Math.hypot(c.x-q.x,c.y-q.y)<1)&&Math.hypot(p.x-q.x,p.y-q.y)<320));}
function localAllowed(p,r){let members=clusterMembers(r);if(reservedForOther(p,r.id)||Math.hypot(p.x-r.x,p.y-r.y)>growthRadius(r))return false;if(!members.some(c=>{let d=Math.hypot(p.x-c.x,p.y-c.y);return d>=195&&d<=330;}))return false;if(!realCities().filter(c=>!c.removed&&c.regionId!==r.id).every(c=>Math.hypot(p.x-c.x,p.y-c.y)>=320))return false;let own=Math.hypot(p.x-r.x,p.y-r.y);if(cityRegions().some(o=>o.id!==r.id&&Math.hypot(p.x-o.x,p.y-o.y)<own+100))return false;return true;}
function previewSeedCluster(p){let centers=cityRegions(),preview=[p],directions=new Set(),choices=growthAvailable.filter(q=>Math.hypot(q.x-p.x,q.y-p.y)<=520&&farEnough(q,p)&&!reservedForOther(q,-1)&&realCities().every(c=>c.removed||Math.hypot(q.x-c.x,q.y-c.y)>=320)&&centers.every(r=>Math.hypot(q.x-r.x,q.y-r.y)>=Math.hypot(q.x-p.x,q.y-p.y)+100));
 for(let i=1;i<8;i++){let eligible=choices.filter(q=>preview.some(c=>{let d=Math.hypot(q.x-c.x,q.y-c.y);return d>=195&&d<=330;}));if(!eligible.length)return null;let dir=q=>(q.x>=p.x?1:0)+(q.y>=p.y?2:0);eligible.sort((a,b)=>((directions.has(dir(a))?1000:0)+Math.abs(Math.hypot(a.x-p.x,a.y-p.y)-230))-((directions.has(dir(b))?1000:0)+Math.abs(Math.hypot(b.x-p.x,b.y-p.y)-230)));let q=eligible[0];preview.push(q);directions.add(dir(q));choices=choices.filter(x=>farEnough(x,q));}return directions.size>=3?preview:null;}
function pick(array){return array[Math.floor(Math.random()*array.length)];}
function findLocal(r){let reserved=(r.reservedPoints||[]).filter(p=>growthAvailable.some(q=>q.x===p.x&&q.y===p.y)&&localAllowed(p,r));if(reserved.length)return pick(reserved);if(r.id>0&&clusterMembers(r).length<8)return null;let choices=growthAvailable.filter(p=>localAllowed(p,r));return choices.length?pick(choices):null;}
function findSeed(first=false){let choices=growthAvailable.filter(p=>{if(reservedForOther(p,-1))return false;let near=Math.min(...realCities().filter(c=>!c.removed).map(c=>Math.hypot(c.x-p.x,c.y-p.y)));if(near<420||near>700)return false;return first?cityRegions().some(r=>{let d=Math.hypot(p.x-r.x,p.y-r.y);return d>=590&&d<=760;}):cityRegions().every(r=>Math.hypot(p.x-r.x,p.y-r.y)>=1000);});
 // Try random order then scan the whole finite pool before declaring no suitable cluster site.
 while(choices.length){let i=Math.floor(Math.random()*choices.length),p=choices.splice(i,1)[0],preview=previewSeedCluster(p);if(preview){pendingSeedPlan=preview;return p;}}return null;}
function addCity(p,r,outlying=false,seed=false){let gs=growthState(),c=makeCity(p.x,p.y,0,Math.floor(rand(0,4)),realCities().length%3);Object.assign(c,{name:names[realCities().length%names.length]+(outlying?'远镇':'·'+r.name),regionId:r.id,dormant:true,openingAt:S.day+2.5,grace:0,discoveredAt:S.day});if(r.id>0||outlying)Object.assign(c,{remote:true,remoteStage:0,regionalGrowth:true});if(outlying)Object.assign(c,{outlying:true});S.cities.push(c);gs.births.push({id:c.id,day:S.day,x:c.x,y:c.y,region:r.id,outlying,seed});growthAvailable=growthAvailable.filter(q=>farEnough(q,c));gs.paused=false;if(!seed)toast('发现 '+c.name+' · 30秒后开放');return c;}
function createStudyRegion(p){let rs=cityRegions(),r={id:rs.length,x:p.x,y:p.y,name:'第'+(rs.length+1)+'城市圈',discoveredAt:S.day,nextLocalAt:Infinity,reservedPoints:pendingSeedPlan};rs.push(r);S.farOffered=true;let gs=growthState();gs.focus=r.id;gs.readyAt=null;addCity(p,r,false,true);updateRegionalExpansion();toast('发现 '+r.name+' · 周边城市将逐步出现');return r;}
function updateGrowthMaturity(){let gs=growthState(),r=cityRegions().find(r=>r.id===gs.focus);if(!r||gs.readyAt!==null||r.id===0)return;if(S.day-r.discoveredAt>=90&&clusterMembers(r,true).length>=8&&growthDirections(r).size>=3){gs.readyAt=S.day+25;gs.maturity.push({id:r.id,day:S.day,readyAt:gs.readyAt,open:clusterMembers(r,true).length,directions:growthDirections(r).size});}}
function findOutlier(){let cs=realCities().filter(c=>!c.removed),rs=cityRegions();let choices=growthAvailable.filter(p=>!reservedForOther(p,-1)&&Math.min(...cs.map(c=>Math.hypot(p.x-c.x,p.y-c.y)))>=330&&Math.min(...cs.map(c=>Math.hypot(p.x-c.x,p.y-c.y)))<=650&&Math.min(...rs.map(r=>Math.hypot(p.x-r.x,p.y-r.y)))>=550);if(!choices.length)return null;let narrow=[];for(let i=0;i<choices.length;i++){let p=choices[i];if(!previewSeedCluster(p)){narrow.push(p);if(narrow.length>=12)break;}}return narrow.length?pick(narrow):null;}
const spawnBeforeAtlas=spawnCity;
spawnCity=function(){if(!activeAtlasMap)return spawnBeforeAtlas();let gs=growthState();if(realCities().filter(c=>c.dormant&&!c.removed).length>=2)return;growthAvailable=freePoints();let rs=cityRegions(),focus=rs.find(r=>r.id===gs.focus);
 if(rs.length===1){if(clusterMembers(rs[0]).length<6){if(S.day<gs.next)return;let p=findLocal(rs[0]);if(p){addCity(p,rs[0]);gs.next=S.day+18;return;}}if(!S.unlocked.includes('rail')||S.day<(gs.firstSeedRetryAt??65))return;let p=findSeed(true);if(p){createStudyRegion(p);gs.next=S.day+12;}else gs.firstSeedRetryAt=S.day+15;return;}
 if(S.day+1e-8<gs.next)return;updateGrowthMaturity();if(gs.readyAt!==null&&S.day>=gs.readyAt){let p=findSeed();if(p){createStudyRegion(p);gs.next=S.day+12;return;}}
 if(Math.random()<.2){let p=findOutlier();if(p){let r=rs.reduce((a,b)=>Math.hypot(p.x-a.x,p.y-a.y)<Math.hypot(p.x-b.x,p.y-b.y)?a:b);addCity(p,r,true);gs.next=S.day+12;return;}}
 let old=rs.filter(r=>r!==focus),targets=old.length&&Math.random()<.2?[pick(old),focus,...old]:[focus,...old];for(let r of targets){let p=findLocal(r);if(p){addCity(p,r);gs.next=S.day+12;return;}}
 let p=findOutlier();if(p){let r=rs.reduce((a,b)=>Math.hypot(p.x-a.x,p.y-a.y)<Math.hypot(p.x-b.x,p.y-b.y)?a:b);addCity(p,r,true);gs.next=S.day+12;return;}gs.paused=true;gs.exhaustedAt??=S.day;gs.next=S.day+15;
};
const rateBeforeOutlying=passengerRate;passengerRate=function(c){return rateBeforeOutlying(c)*(activeAtlasMap&&c.outlying?.35:1);};
const initializeBeforeAtlas=initializeRegionalGrowth;
initializeRegionalGrowth=function(){if(!activeAtlasMap)return initializeBeforeAtlas();};
const tickBeforeMapGrowth=tick;
tick=function(dt){if(!activeAtlasMap)return tickBeforeMapGrowth(dt);growthState();tickBeforeMapGrowth(dt);if(S.lives>0){let gs=growthState();if(Math.floor(S.day)!==gs.lastDay){gs.lastDay=Math.floor(S.day);updateGrowthMaturity();}if(S.day>=gs.next)spawnCity();}};
secondCircleFormed=function(){return cityRegions().some(r=>r.id>0&&clusterMembers(r,true).length>=3);};
// Preserve the original first-circle18-day schedule and earliest second seed65.
const spawnBeforeDateGuard=spawnCity;
spawnCity=function(){if(!activeAtlasMap)return spawnBeforeDateGuard();let gs=growthState(),rs=cityRegions();if(rs.length===1){if(clusterMembers(rs[0]).length<6&&S.day<gs.next)return;if(clusterMembers(rs[0]).length>=6&&(!S.unlocked.includes('rail')||S.day<(gs.firstSeedRetryAt??65)))return;}else if(S.day+1e-8<gs.next)return;return spawnBeforeDateGuard();};
